'use strict';
/** Production presentation layer. Never touches scoring or question selection. */
window.ArcoVisual=(()=>{
 const art={"piano": "data:image/webp;base64,", "score": "data:image/webp;base64,", "city": "data:image/webp;base64,", "duel": "data:image/webp;base64,"};
 const KEY='arco.visual.preferences.v1', root=document.documentElement;
 let preferences={motion:true};
 try{const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw&&typeof raw.motion==='boolean')preferences.motion=raw.motion;}catch(_){}
 const media=matchMedia('(prefers-reduced-motion: reduce)');
 let sectionObserver=null;
 function effectiveMotion(){return preferences.motion&&!media.matches;}
 function syncMotion(){
  root.dataset.motion=effectiveMotion()?'on':'off';
  document.querySelectorAll('[data-visual-action="motion"]').forEach(b=>{b.setAttribute('aria-pressed',String(effectiveMotion()));b.textContent=media.matches?'已依系統減少動態':preferences.motion?'動態效果開啟':'動態效果關閉';});
  const box=document.querySelector('#visual-motion');if(box){box.checked=preferences.motion;box.disabled=media.matches;}
 }
 function setMotion(value){preferences.motion=!!value;try{localStorage.setItem(KEY,JSON.stringify(preferences));}catch(_){}syncMotion();}
 function staff(){return `<svg class="hero-staff" viewBox="0 0 650 170" aria-hidden="true" focusable="false">${[0,10,20,30,40].map(n=>`<path d="M5 ${98+n} C120 ${145+n} 180 ${12+n} 340 ${48+n} S530 ${150+n} 647 ${28+n}"/>`).join('')}<g><ellipse cx="171" cy="82" rx="7" ry="4" transform="rotate(-24 171 82)"/><path class="note-stem" d="M177 79V46"/><ellipse cx="363" cy="80" rx="7" ry="4" transform="rotate(-24 363 80)"/><path class="note-stem" d="M369 77V44"/><ellipse cx="557" cy="94" rx="7" ry="4" transform="rotate(-24 557 94)"/><path class="note-stem" d="M563 91V58"/></g></svg>`;}
 function observeSections(){
  sectionObserver?.disconnect();
  const sections=[...document.querySelectorAll('.lesson-page #lesson-read,.lesson-page #lesson-practice,.lesson-page #lesson-mission,.lesson-page #lesson-challenge')];
  if(!sections.length)return;
  const buttons=[...document.querySelectorAll('.lesson-roadmap [data-target]')];
  function update(){
   const header=document.querySelector('.header')?.getBoundingClientRect().bottom||88;
   let current=sections[0];
   for(const section of sections){if(section.id==='lesson-challenge'&&innerWidth>900&&document.activeElement.id!=='lesson-challenge')continue;const rect=section.getBoundingClientRect();if(rect.top<=header+160&&rect.bottom>header+20)current=section;}
   buttons.forEach(b=>{const active=b.dataset.target===current.id;b.classList.toggle('is-active',active);if(active)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});
  }
  sectionObserver=new IntersectionObserver(update,{rootMargin:'-120px 0px -45% 0px',threshold:[0,.1,.5,1]});sections.forEach(s=>sectionObserver.observe(s));
  update();
 }
 function refresh(){
  syncMotion();
  // A section highlight indicates reading position, never a completion claim.
  observeSections();
 }
 function enhanceSettings(){
  const d=document.getElementById('settings');
  if(!d?.open||!d.querySelector('#setting-volume')||d.querySelector('.visual-settings'))return;
  const section=document.createElement('div');section.className='setting-row visual-settings';
  section.innerHTML=`<div><h3>視覺動態</h3><p>${media.matches?'已遵循系統的減少動態設定。':'首頁開場、音符與通關回饋。關閉不影響發聲或答題。'}</p></div><label class="switch"><input id="visual-motion" type="checkbox" aria-label="視覺動態"><span></span></label>`;
  d.querySelector('.settings-buttons')?.before(section);syncMotion();
 }
 document.addEventListener('click',e=>{
  const b=e.target.closest('[data-visual-action]');if(!b)return;
  if(b.dataset.visualAction==='motion'){
   if(media.matches){window.ARCO?.notify('目前依系統設定減少動態。');return;}
   setMotion(!preferences.motion);
  }
 });
 document.addEventListener('change',e=>{if(e.target.id==='visual-motion')setMotion(e.target.checked);});
 function audioState(playing){
  document.body.dataset.sound=playing?'playing':'stopped';
  document.querySelectorAll('[data-action="home-demo"]').forEach(b=>{b.textContent=playing?'停止示範':'播放 C 大調';b.setAttribute('aria-pressed',String(playing));});
 }
 document.addEventListener('arco:audio-start',()=>audioState(true));
 document.addEventListener('arco:audio-stop',()=>audioState(false));
 document.addEventListener('visibilitychange',()=>{
  // Do not keep sound or visual pulse running in a hidden tab; game clocks remain untouched.
  if(document.hidden)window.ARCO?.stopAudio();
 });
 const settingsObserver=new MutationObserver(enhanceSettings);
 settingsObserver.observe(document.getElementById('settings'),{childList:true,attributes:true,attributeFilter:['open']});
 media.addEventListener('change',()=>{syncMotion();const row=document.querySelector('.visual-settings');if(row)row.remove();enhanceSettings();});
 syncMotion();
 function resetPreferences(){preferences={motion:true};syncMotion();}
 return {art,staff,refresh,setMotion,effectiveMotion,resetPreferences};
})();
